//! Ensuring a document's derived files as a deploy or publish step.
use crate::prelude::*;
use beet_action::prelude::*;
use beet_core::prelude::*;
use beet_net::prelude::*;

/// `<Derive/>`: ensure every derived file this document declares, so the step
/// after it publishes current ones.
///
/// Each [`Derivation`] in the document is checked against its sources,
/// regenerated by its producing action when stale or missing and left alone
/// otherwise, so a run where nothing changed costs one comparison per file.
/// Under a [`RepoStage`] a derivation in the repo store is ensured in the
/// staging dir, so a deploy publishes current derived files and writes nothing
/// into the checkout; one in any other store is no part of the stage and is
/// ensured where it lives. Elsewhere (the local `assets` verb, the asset
/// publish) each is ensured in the store it resolves by ancestry. The
/// placement rule is [`DirCopy`]'s, so the one tag serves all three.
///
/// ```bsx
/// <RepoStage src="site">
///     <DirCopy src="assets" dest="assets" paths="databases/country.mmdb"/>
///     <Derive/>
/// </RepoStage>
/// ```
#[action]
#[derive(Debug, Default, Component, Reflect)]
#[reflect(Component, Default)]
pub async fn Derive(
	cx: ActionContext<Request>,
) -> Result<Outcome<Request, Response>> {
	let world = cx.world();
	let caller = cx.id();
	let targets = world
		.with(move |world: &mut World| Derive::targets(world, caller))
		.await?;
	for (entity, store) in &targets {
		Derivation::ensure(&world, *entity, store).await?;
	}
	debug!("ensured {} derived file(s)", targets.len());
	Pass(cx.input).xok()
}

impl Derive {
	/// Every derivation in the document `caller` belongs to, with the store
	/// each is ensured in.
	fn targets(
		world: &mut World,
		caller: Entity,
	) -> Result<Vec<(Entity, BlobStore)>> {
		let (root, stage) = world
			.with_state::<(AncestorQuery<&RepoStage>, StackQuery), _>(
				|(stages, stacks)| -> Result<_> {
					let stage = match stages.get(caller) {
						Ok(_) => Some(RepoStage::dir(&stacks, caller)?),
						Err(_) => None,
					};
					(stages.root_ancestor(caller), stage).xok()
				},
			)?;
		let repo = RepoStore::get(world).ok();
		Derivation::declared(world, root)
			.into_iter()
			.map(|entity| {
				let store = world.with_state::<AncestorQuery<&BlobStore>, _>(
					|stores| stores.get(entity).cloned(),
				)?;
				let store = match (&stage, &repo) {
					(Some(stage), Some(repo)) => {
						Self::staged(stage, repo, store)
					}
					_ => store,
				};
				(entity, store).xok()
			})
			.collect()
	}

	/// `store` moved into the staging dir when it is the repo store or scoped
	/// out of it, the stage being the repo store's published copy.
	fn staged(
		stage: &AbsPath,
		repo: &BlobStore,
		store: BlobStore,
	) -> BlobStore {
		match store.subdir().strip_prefix(&repo.subdir()) {
			Some(subdir) if store.root_key() == repo.root_key() => {
				let staged = BlobStore::new(FsStore::new(stage.clone()));
				match subdir.is_empty() {
					true => staged,
					false => staged.with_subdir(subdir),
				}
			}
			_ => store,
		}
	}
}

#[cfg(test)]
mod test {
	use crate::prelude::*;
	use beet_action::prelude::*;
	use beet_core::prelude::*;
	use beet_net::prelude::*;
	use beet_router::prelude::*;

	const SOURCE: &str = "notes.md";
	const DERIVED: &str = "derived/notes.json";

	/// A derivation of [`DERIVED`] from [`SOURCE`], in whatever store it is
	/// ensured in.
	fn derivation() -> impl Bundle {
		(
			Derivation::new(DERIVED),
			Action::<BlobStore, EntityBody>::new_async(
				async |cx: ActionContext<BlobStore>| {
					let bytes = cx.input.get(&RelPath::new(SOURCE)).await?;
					EntityBody::default().with(&Provenance::new([
						ProvenanceSource::file(SOURCE, &bytes),
					]))
				},
			),
		)
	}

	/// A site dir holding [`SOURCE`] at its root and under `assets/`, and a
	/// world whose repo store it is, the root returned to hang a document
	/// off.
	fn site(deployment: Deployment) -> (TempDir, World, Entity) {
		let dir = TempDir::new_ws().unwrap();
		let site = dir.path().join("site");
		for path in [SOURCE, &format!("assets/{SOURCE}")] {
			fs_ext::write(site.join(path), "# notes").unwrap();
		}
		let mut world =
			(AsyncPlugin, BootstrapPlugin, InfraPlugin).into_world();
		world.insert_resource(deployment);
		let root = world
			.spawn((BlobStore::new(FsStore::new(site)), RepoStore))
			.id();
		(dir, world, root)
	}

	/// Whether the site dir under `dir` holds `path`.
	fn exists(dir: &AbsPath, path: &str) -> bool {
		fs_ext::exists(dir.join(path)).unwrap()
	}

	/// Outside a stage a derivation is ensured in the store it resolves.
	#[beet_core::test]
	async fn ensures_in_the_resolved_store() {
		let (dir, mut world, root) = site(Deployment::default_local().0);
		world.spawn((ChildOf(root), derivation()));
		world
			.spawn((ChildOf(root), ExchangeSequence, children![Derive]))
			.exchange(Request::get(""))
			.await
			.into_result()
			.await
			.unwrap();
		exists(&dir.path().join("site"), DERIVED).xpect_true();
	}

	/// Under a stage a derivation in the repo store, or scoped out of it, is
	/// ensured in the staging dir and never in the checkout, while one in
	/// another store is ensured where it lives.
	#[beet_core::test]
	async fn ensures_the_repo_store_in_the_stage() {
		let (deployment, _work_dir) = Deployment::default_local();
		let (dir, mut world, root) = site(deployment.clone());
		let elsewhere = BlobStore::temp();
		elsewhere
			.insert(&RelPath::new(SOURCE), "# elsewhere")
			.await
			.unwrap();
		world.spawn((ChildOf(root), derivation()));
		world.spawn((
			ChildOf(root),
			DirPath(RelPath::new("assets")),
			children![derivation()],
		));
		world.spawn((
			ChildOf(root),
			elsewhere.clone(),
			children![derivation()],
		));
		let source = dir.path().join("site").into_ws_path().unwrap();
		world
			.spawn((
				ChildOf(root),
				Stack::new("app"),
				ExchangeSequence,
				children![(RepoStage::new(source), children![Derive])],
			))
			.exchange(Request::get(""))
			.await
			.into_result()
			.await
			.unwrap();
		let stage = deployment
			.work_directory(
				&Stack::new("app").resolve(&PackageConfig::default()),
			)
			.into_abs()
			.join("repo");
		exists(&stage, DERIVED).xpect_true();
		exists(&stage, &format!("assets/{DERIVED}")).xpect_true();
		let site = dir.path().join("site");
		exists(&site, DERIVED).xpect_false();
		exists(&site, &format!("assets/{DERIVED}")).xpect_false();
		elsewhere
			.exists(&RelPath::new(DERIVED))
			.await
			.unwrap()
			.xpect_true();
	}
}
